//! Passive protocol-major-1 metadata; capabilities are not authorization.
//! Legacy requests with none of the three headers remain supported for all of
//! major 1. Dropping this path requires a new major and documented migration.
//! IDs are generated by scripts/rust/protocol-manifest.py --check: SHA256 of
//! compact UTF-8 JSON, recursively sorted keys, ASCII escaping, operations sorted
//! by (path, method), excluding manifestId. No workspace facts enter the identity.
use axum::{
    Router,
    extract::Request,
    http::{HeaderMap, StatusCode},
    middleware::{self, Next},
    response::{IntoResponse, Response},
    routing::get,
};
use std::sync::Arc;

const FULL_MANIFEST: &str = include_str!("../../../protocol/http-v1.json");
const PUBLIC_MANIFEST: &str = r#"{"format":"rentemester-http-protocol/1","manifestId":"3b39914fa4bc7d8087a6176de4fe396021b85d9240f61245f91ae712baf0297c","operations":[{"capability":"GET /api/agent-about","method":"GET","path":"/api/agent-about"},{"capability":"HEAD /api/agent-about","method":"HEAD","path":"/api/agent-about"},{"capability":"GET /api/agent-capabilities","method":"GET","path":"/api/agent-capabilities"},{"capability":"HEAD /api/agent-capabilities","method":"HEAD","path":"/api/agent-capabilities"},{"capability":"GET /api/agent-workflows/{id}","method":"GET","path":"/api/agent-workflows/{id}"},{"capability":"HEAD /api/agent-workflows/{id}","method":"HEAD","path":"/api/agent-workflows/{id}"},{"capability":"GET /api/health","method":"GET","path":"/api/health"},{"capability":"HEAD /api/health","method":"HEAD","path":"/api/health"},{"capability":"GET /api/protocol","method":"GET","path":"/api/protocol"},{"capability":"HEAD /api/protocol","method":"HEAD","path":"/api/protocol"}],"protocolMajor":1,"wireProfiles":["legacy-react-v1","rust-http-v1"]}"#;
const HEADERS: [&str; 3] = [
    "x-rentemester-protocol",
    "x-rentemester-manifest",
    "x-rentemester-wire-profile",
];

pub fn install(router: Router, connected: bool) -> Router {
    let body = if connected {
        FULL_MANIFEST
    } else {
        PUBLIC_MANIFEST
    };
    assert!(body.len() <= 1024 * 1024);
    let manifest: serde_json::Value = serde_json::from_str(body).expect("checked static manifest");
    let manifest = Arc::new(manifest);
    router
        .route(
            "/api/protocol",
            get(move || async move {
                (
                    [
                        ("content-type", "application/json"),
                        ("cache-control", "no-store"),
                    ],
                    body,
                )
            }),
        )
        .layer(middleware::from_fn(move |request: Request, next: Next| {
            let manifest = manifest.clone();
            async move {
                // Metadata is always passive, including requests with stray credentials.
                if request.uri().path() != "/api/protocol"
                    && !admitted(
                        request.headers(),
                        &manifest,
                        request.method().as_str(),
                        request.uri().path(),
                    )
                {
                    return incompatible();
                }
                next.run(request).await
            }
        }))
}

fn incompatible() -> Response {
    (StatusCode::CONFLICT, [("content-type", "application/json")],
     r#"{"ok":false,"code":"protocol_incompatible","errors":["HTTP protocol negotiation is incompatible"]}"#).into_response()
}

fn admitted(headers: &HeaderMap, manifest: &serde_json::Value, method: &str, path: &str) -> bool {
    if HEADERS.iter().all(|key| !headers.contains_key(*key)) {
        return true; // Explicit unversioned legacy-v1 compatibility, not auth.
    }
    let one = |key| {
        let mut values = headers.get_all(key).iter();
        let first = values.next()?.to_str().ok()?;
        if values.next().is_some() {
            None
        } else {
            Some(first)
        }
    };
    one(HEADERS[0]) == Some("1")
        && one(HEADERS[1]) == manifest["manifestId"].as_str()
        && one(HEADERS[2]).is_some_and(|profile| {
            manifest["wireProfiles"]
                .as_array()
                .unwrap()
                .iter()
                .any(|p| p == profile)
        })
        && manifest["operations"]
            .as_array()
            .unwrap()
            .iter()
            .any(|op| op["method"] == method && matches_path(op["path"].as_str().unwrap(), path))
}

fn matches_path(template: &str, path: &str) -> bool {
    let left: Vec<_> = template.split('/').collect();
    let right: Vec<_> = path.split('/').collect();
    left.len() == right.len()
        && left.iter().zip(right).all(|(a, b)| {
            if a.starts_with('{') && a.ends_with('}') {
                !b.is_empty()
            } else {
                *a == b
            }
        })
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicUsize, Ordering};

    #[test]
    fn protocol_source_bound() {
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        assert!(
            std::process::Command::new("python3")
                .arg(root.join("scripts/rust/protocol-manifest.py"))
                .arg("--check")
                .status()
                .unwrap()
                .success()
        );
    }

    #[test]
    fn protocol_exact_segments() {
        assert!(matches_path("/api/x/{id}", "/api/x/a"));
        for path in ["/api/x/", "/api/x/a/b", "/api/x", "/api/xx/a"] {
            assert!(!matches_path("/api/x/{id}", path));
        }
    }

    #[tokio::test]
    async fn protocol_refuses_before_handler_and_preserves_auth() {
        let calls = Arc::new(AtomicUsize::new(0));
        let count = calls.clone();
        let router = Router::new().route(
            "/api/setup/first-owner",
            axum::routing::post(move || {
                let count = count.clone();
                async move {
                    count.fetch_add(1, Ordering::SeqCst);
                    StatusCode::UNAUTHORIZED
                }
            }),
        );
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let task = tokio::spawn(async move {
            axum::serve(listener, install(router, true)).await.unwrap();
        });
        let client = reqwest::Client::new();
        let url = format!("http://{addr}/api/setup/first-owner");
        let id = serde_json::from_str::<serde_json::Value>(FULL_MANIFEST).unwrap()["manifestId"]
            .as_str()
            .unwrap()
            .to_owned();
        for (major, manifest, profile) in [
            ("2", id.as_str(), "rust-http-v1"),
            ("1", "stale", "rust-http-v1"),
            ("1", id.as_str(), "unknown"),
            ("1", "", ""),
        ] {
            assert_eq!(
                client
                    .post(&url)
                    .header(HEADERS[0], major)
                    .header(HEADERS[1], manifest)
                    .header(HEADERS[2], profile)
                    .send()
                    .await
                    .unwrap()
                    .status(),
                StatusCode::CONFLICT
            );
        }
        assert_eq!(calls.load(Ordering::SeqCst), 0);
        assert_eq!(
            client
                .post(&url)
                .header(HEADERS[0], "1")
                .header(HEADERS[1], &id)
                .header(HEADERS[2], "rust-http-v1")
                .send()
                .await
                .unwrap()
                .status(),
            StatusCode::UNAUTHORIZED
        );
        assert_eq!(calls.load(Ordering::SeqCst), 1);
        assert_eq!(
            client.post(&url).send().await.unwrap().status(),
            StatusCode::UNAUTHORIZED
        );
        assert_eq!(calls.load(Ordering::SeqCst), 2);
        let metadata = client
            .get(format!("http://{addr}/api/protocol"))
            .send()
            .await
            .unwrap();
        assert_eq!(metadata.status(), StatusCode::OK);
        assert_eq!(calls.load(Ordering::SeqCst), 2);
        task.abort();
    }
}
